UPDATE payment AS pay
INNER JOIN subscribe AS sub
    ON pay.subscribe_id = sub.subscribe_id
JOIN subscription AS sbt
	ON sub.subscription_id = sbt.subscription_id
JOIN plan AS pl 
    ON sbt.plan_id = pl.plan_id
SET 
    pay.payed_cost = pl.cost,
    pay.will_pay_cost = pl.cost;
    
SELECT * FROM payment;

COMMIT;